I have an AMM smart contract. Write comprehensive unit tests for it. Cover pool creation, adding/removing liquidity, swaps, edge cases, and error conditions.

```move
module amm::pool;

use sui::balance::{Self, Balance};
use sui::coin::{Self, Coin};

const EInsufficientLiquidity: u64 = 0;
const EZeroAmount: u64 = 1;

public struct Pool<phantom A, phantom B> has key {
    id: UID,
    reserve_a: Balance<A>,
    reserve_b: Balance<B>,
    lp_supply: u64,
}

public fun create<A, B>(a: Coin<A>, b: Coin<B>, ctx: &mut TxContext): Pool<A, B> {
    assert!(a.value() > 0 && b.value() > 0, EZeroAmount);
    let lp_supply = a.value();
    Pool {
        id: object::new(ctx),
        reserve_a: a.into_balance(),
        reserve_b: b.into_balance(),
        lp_supply,
    }
}

public fun add_liquidity<A, B>(pool: &mut Pool<A, B>, a: Coin<A>, b: Coin<B>): u64 {
    assert!(a.value() > 0 && b.value() > 0, EZeroAmount);
    let minted = a.value();
    pool.reserve_a.join(a.into_balance());
    pool.reserve_b.join(b.into_balance());
    pool.lp_supply = pool.lp_supply + minted;
    minted
}

public fun remove_liquidity<A, B>(
    pool: &mut Pool<A, B>, lp_amount: u64, ctx: &mut TxContext,
): (Coin<A>, Coin<B>) {
    assert!(lp_amount > 0 && lp_amount <= pool.lp_supply, EInsufficientLiquidity);
    let share_a = pool.reserve_a.value() * lp_amount / pool.lp_supply;
    let share_b = pool.reserve_b.value() * lp_amount / pool.lp_supply;
    pool.lp_supply = pool.lp_supply - lp_amount;
    (
        coin::from_balance(pool.reserve_a.split(share_a), ctx),
        coin::from_balance(pool.reserve_b.split(share_b), ctx),
    )
}

public fun swap_a_for_b<A, B>(
    pool: &mut Pool<A, B>, a: Coin<A>, ctx: &mut TxContext,
): Coin<B> {
    let amount_in = a.value();
    assert!(amount_in > 0, EZeroAmount);
    let out = pool.reserve_b.value() * amount_in / (pool.reserve_a.value() + amount_in);
    assert!(out > 0 && out < pool.reserve_b.value(), EInsufficientLiquidity);
    pool.reserve_a.join(a.into_balance());
    coin::from_balance(pool.reserve_b.split(out), ctx)
}

public fun reserves<A, B>(pool: &Pool<A, B>): (u64, u64) {
    (pool.reserve_a.value(), pool.reserve_b.value())
}

public fun lp_supply<A, B>(pool: &Pool<A, B>): u64 { pool.lp_supply }
```
